 p=R/'journal'/slug/'index.html';s=p.read_text();dates=re.findall(r'"datePublished"\s*:\s*"([^"]+)"',s);i=s.index('</article>');assert 'id="day6-'not in s;s=modified(s[:i]+block+s[i:]);assert re.findall(r'"datePublished"\s*:\s*"([^"]+)"',s)==dates;p.write_text(s);ledger.append(dict(id=oid,slug=slug,decision='updated',datePublished=dates))
